const input = $input.first().json;

const errors = [];

// -----------------------------
// Basic structure validation
// -----------------------------

if (!input.customer || typeof input.customer !== 'object') {
  errors.push('Customer information is required.');
}

if (!Array.isArray(input.items) || input.items.length === 0) {
  errors.push('At least one quote item is required.');
}

// -----------------------------
// Customer validation
// -----------------------------

if (input.customer) {
  if (
    !input.customer.name ||
    typeof input.customer.name !== 'string' ||
    input.customer.name.trim() === ''
  ) {
    errors.push('Customer name is required.');
  }

  if (
    !input.customer.email ||
    typeof input.customer.email !== 'string' ||
    input.customer.email.trim() === ''
  ) {
    errors.push('Customer email is required.');
  } else {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    if (!emailRegex.test(input.customer.email.trim())) {
      errors.push('Customer email format is invalid.');
    }
  }
}

// -----------------------------
// Items validation
// -----------------------------

if (Array.isArray(input.items)) {
  input.items.forEach((item, index) => {
    const itemNumber = index + 1;

    if (!item || typeof item !== 'object') {
      errors.push(`Item ${itemNumber} is invalid.`);
      return;
    }

    if (
      !item.name ||
      typeof item.name !== 'string' ||
      item.name.trim() === ''
    ) {
      errors.push(`Item ${itemNumber}: name is required.`);
    }

    if (
      item.description !== undefined &&
      typeof item.description !== 'string'
    ) {
      errors.push(`Item ${itemNumber}: description must be text.`);
    }

    if (
      typeof item.quantity !== 'number' ||
      !Number.isFinite(item.quantity) ||
      item.quantity <= 0
    ) {
      errors.push(
        `Item ${itemNumber}: quantity must be a number greater than 0.`
      );
    }

    if (
      typeof item.unit_price !== 'number' ||
      !Number.isFinite(item.unit_price) ||
      item.unit_price < 0
    ) {
      errors.push(
        `Item ${itemNumber}: unit price must be a number greater than or equal to 0.`
      );
    }
  });
}

// -----------------------------
// Discount validation
// -----------------------------

if (
  typeof input.discount !== 'number' ||
  !Number.isFinite(input.discount) ||
  input.discount < 0
) {
  errors.push('Discount must be a number greater than or equal to 0.');
}

// -----------------------------
// Tax validation
// -----------------------------

if (
  typeof input.tax !== 'number' ||
  !Number.isFinite(input.tax) ||
  input.tax < 0 ||
  input.tax > 100
) {
  errors.push('Tax must be a percentage between 0 and 100.');
}

// -----------------------------
// Currency validation
// -----------------------------

if (
  !input.currency ||
  typeof input.currency !== 'string' ||
  input.currency.trim() === ''
) {
  errors.push('Currency is required.');
}

// -----------------------------
// Quote validity validation
// -----------------------------

if (
  typeof input.validity_days !== 'number' ||
  !Number.isInteger(input.validity_days) ||
  input.validity_days <= 0
) {
  errors.push('Validity days must be a positive whole number.');
}

// -----------------------------
// Final result
// -----------------------------

const valid = errors.length === 0;

return [
  {
    json: {
      valid,
      errors,
      data: input
    }
  }
];

const input = $input.first().json;

if (!input.output) {
  throw new Error("AI output was not found.");
}

let parsed;

try {
  parsed = JSON.parse(input.output);
} catch (error) {
  throw new Error(
    `AI output is not valid JSON: ${error.message}`
  );
}

if (!parsed || typeof parsed !== "object") {
  throw new Error("Parsed AI output is not a valid object.");
}

if (!Array.isArray(parsed.items)) {
  throw new Error("AI output must contain an items array.");
}

return [
  {
    json: parsed
  }
];

const input = $input.first().json.data;

const now = new Date();

const year = now.getFullYear();

const timestamp = Date.now();

const quoteId = `QT-${year}-${timestamp}`;

return [
  {
    json: {
      ...$input.first().json,
      data: {
        ...input,
        quote_id: quoteId,
        created_at: now.toISOString()
      }
    }
  }
];

const input = $input.first().json;
const data = input.data;

// ============================================================
// HELPERS
// ============================================================

function roundMoney(value) {
  return Math.round((Number(value) + Number.EPSILON) * 100) / 100;
}

function normalizeDiscount(discount, defaultType = "fixed") {
  // Phase 1 compatibility:
  // discount: 5000
  // means fixed ₹5,000

  if (discount === undefined || discount === null) {
    return {
      type: defaultType,
      value: 0
    };
  }

  if (typeof discount === "number") {
    return {
      type: "fixed",
      value: Math.max(Number(discount), 0)
    };
  }

  if (typeof discount === "object") {
    const type =
      discount.type === "percentage" ||
      discount.type === "percent"
        ? "percentage"
        : "fixed";

    const value = Number(discount.value || 0);

    return {
      type,
      value: Math.max(value, 0)
    };
  }

  return {
    type: "fixed",
    value: 0
  };
}

function calculateDiscount(baseAmount, discount) {
  const normalized = normalizeDiscount(discount);

  if (normalized.type === "percentage") {
    const percentage = Math.min(normalized.value, 100);

    return {
      type: "percentage",
      value: percentage,
      amount: roundMoney(
        baseAmount * (percentage / 100)
      )
    };
  }

  return {
    type: "fixed",
    value: roundMoney(normalized.value),
    amount: roundMoney(
      Math.min(normalized.value, baseAmount)
    )
  };
}


// ============================================================
// VALIDATE ITEMS
// ============================================================

if (!Array.isArray(data.items) || data.items.length === 0) {
  throw new Error("At least one quote item is required.");
}


// ============================================================
// PROCESS ITEMS
// ============================================================

const items = data.items.map((item, index) => {

  const quantity = Number(item.quantity);
  const unitPrice = Number(item.unit_price);

  if (!Number.isFinite(quantity) || quantity <= 0) {
    throw new Error(
      `Item ${index + 1}: quantity must be greater than 0.`
    );
  }

  if (!Number.isFinite(unitPrice) || unitPrice < 0) {
    throw new Error(
      `Item ${index + 1}: unit price must be 0 or greater.`
    );
  }

  // ----------------------------------------------------------
  // Gross line total
  // ----------------------------------------------------------

  const grossLineTotal = roundMoney(
    quantity * unitPrice
  );

  // ----------------------------------------------------------
  // Optional item handling
  //
  // Backward compatible:
  // If optional is not provided, item is included.
  //
  // If:
  // optional: true
  // selected: false
  //
  // the item is excluded from pricing.
  // ----------------------------------------------------------

  const isOptional = item.optional === true;

  const isSelected =
    item.selected === undefined
      ? true
      : Boolean(item.selected);

  const includedInQuote =
    !isOptional || isSelected;

  // ----------------------------------------------------------
  // Item-level discount
  // ----------------------------------------------------------

  let itemDiscount = {
    type: "fixed",
    value: 0,
    amount: 0
  };

  if (includedInQuote) {
    itemDiscount = calculateDiscount(
      grossLineTotal,
      item.discount
    );
  }

  // ----------------------------------------------------------
  // Net line total
  // ----------------------------------------------------------

  const lineTotal = includedInQuote
    ? roundMoney(
        Math.max(
          grossLineTotal - itemDiscount.amount,
          0
        )
      )
    : 0;

  return {
    ...item,

    quantity,

    unit_price: roundMoney(unitPrice),

    optional: isOptional,

    selected: isSelected,

    included_in_quote: includedInQuote,

    gross_line_total: grossLineTotal,

    item_discount: {
      type: itemDiscount.type,
      value: itemDiscount.value,
      amount: itemDiscount.amount
    },

    line_total: lineTotal
  };
});


// ============================================================
// ITEM TOTALS
// ============================================================

const grossSubtotal = roundMoney(
  items.reduce(
    (sum, item) =>
      sum + (
        item.included_in_quote
          ? item.gross_line_total
          : 0
      ),
    0
  )
);

const itemDiscountTotal = roundMoney(
  items.reduce(
    (sum, item) =>
      sum + (
        item.included_in_quote
          ? item.item_discount.amount
          : 0
      ),
    0
  )
);

const subtotal = roundMoney(
  items.reduce(
    (sum, item) =>
      sum + (
        item.included_in_quote
          ? item.line_total
          : 0
      ),
    0
  )
);


// ============================================================
// OVERALL DISCOUNT
// ============================================================

const overallDiscount = calculateDiscount(
  subtotal,
  data.discount
);

const overallDiscountAmount =
  overallDiscount.amount;

const discountedSubtotal = roundMoney(
  Math.max(
    subtotal - overallDiscountAmount,
    0
  )
);


// ============================================================
// ADDITIONAL CHARGES
// ============================================================

const additionalChargesInput =
  Array.isArray(data.additional_charges)
    ? data.additional_charges
    : [];

const additionalCharges =
  additionalChargesInput.map((charge, index) => {

    const amount = Number(charge.amount);

    if (!Number.isFinite(amount) || amount < 0) {
      throw new Error(
        `Additional charge ${index + 1}: amount must be 0 or greater.`
      );
    }

    const taxable =
      charge.taxable === undefined
        ? true
        : Boolean(charge.taxable);

    return {
      name:
        String(
          charge.name ||
          `Additional Charge ${index + 1}`
        ).trim(),

      amount: roundMoney(amount),

      taxable
    };
  });

const additionalChargesTotal = roundMoney(
  additionalCharges.reduce(
    (sum, charge) =>
      sum + charge.amount,
    0
  )
);


// ============================================================
// TAXABLE ADDITIONAL CHARGES
// ============================================================

const taxableAdditionalCharges =
  roundMoney(
    additionalCharges
      .filter(charge => charge.taxable)
      .reduce(
        (sum, charge) =>
          sum + charge.amount,
        0
      )
  );


// ============================================================
// TAXABLE AMOUNT
// ============================================================

const taxableAmount = roundMoney(
  discountedSubtotal +
  taxableAdditionalCharges
);


// ============================================================
// TAX
// ============================================================

const taxRate = Number(data.tax || 0);

if (
  !Number.isFinite(taxRate) ||
  taxRate < 0 ||
  taxRate > 100
) {
  throw new Error(
    "Tax rate must be between 0 and 100."
  );
}

const taxAmount = roundMoney(
  taxableAmount *
  (taxRate / 100)
);


// ============================================================
// GRAND TOTAL
// ============================================================

const total = roundMoney(
  discountedSubtotal +
  additionalChargesTotal +
  taxAmount
);


// ============================================================
// PRICING OBJECT
// ============================================================

const pricing = {

  // Phase-1 fields preserved
  subtotal,

  discount: overallDiscountAmount,

  taxable_amount:
    taxableAmount,

  tax_rate:
    roundMoney(taxRate),

  tax_amount:
    taxAmount,

  total,

  // Phase-2 fields
  gross_subtotal:
    grossSubtotal,

  item_discount_total:
    itemDiscountTotal,

  overall_discount: {
    type:
      overallDiscount.type,

    value:
      overallDiscount.value,

    amount:
      overallDiscountAmount
  },

  discounted_subtotal:
    discountedSubtotal,

  additional_charges:
    additionalCharges,

  additional_charges_total:
    additionalChargesTotal
};


// ============================================================
// RETURN UPDATED DATA
// ============================================================

return [
  {
    json: {
      ...input,

      data: {
        ...data,

        items,

        pricing
      }
    }
  }
];

const input = $input.first().json;

// ============================================================
// SOURCE DATA
// ============================================================
//
// Advanced Pricing Engine output:
// {
//   valid: true,
//   errors: [],
//   data: {
//     customer,
//     items,
//     discount,
//     tax,
//     currency,
//     validity_days,
//     quote_id,
//     created_at,
//     pricing
//   }
// }
//
// ============================================================

const data = input.data || {};


// ============================================================
// VALIDATION
// ============================================================

if (!data.quote_id) {
  throw new Error("Quote ID is missing.");
}

if (!data.created_at) {
  throw new Error("Created timestamp is missing.");
}

if (
  !data.customer ||
  typeof data.customer !== "object"
) {
  throw new Error("Customer data is missing.");
}

if (
  !Array.isArray(data.items)
) {
  throw new Error("Items array is missing.");
}

if (
  !data.pricing ||
  typeof data.pricing !== "object"
) {
  throw new Error(
    "Pricing data is missing. " +
    "Quote Object must receive the output of the Advanced Pricing Engine."
  );
}


// ============================================================
// CUSTOMER
// ============================================================

const customer = {
  name:
    data.customer.name || "",

  email:
    data.customer.email || "",

  phone:
    data.customer.phone || "",

  address:
    data.customer.address || ""
};


// ============================================================
// ITEMS
// ============================================================

const items = data.items.map((item) => {

  const quantity =
    Number(item.quantity || 0);

  const unitPrice =
    Number(item.unit_price || 0);

  const lineTotal =
    Number(
      item.line_total ??
      item.gross_line_total ??
      quantity * unitPrice
    );

  return {
    name:
      item.name || "",

    description:
      item.description || "",

    quantity,

    unit_price:
      unitPrice,

    line_total:
      Number(lineTotal.toFixed(2)),

    // ------------------------------
    // Phase-2 fields
    // ------------------------------

    optional:
      item.optional ?? false,

    selected:
      item.selected ?? true,

    included_in_quote:
      item.included_in_quote ?? true,

    gross_line_total:
      Number(
        (
          item.gross_line_total ??
          lineTotal
        ).toFixed(2)
      ),

    item_discount:
      item.item_discount || {
        type: "fixed",
        value: 0,
        amount: 0
      }
  };
});


// ============================================================
// PRICING
// ============================================================

const sourcePricing =
  data.pricing;

const pricing = {

  // ------------------------------------------
  // Phase-1 pricing fields
  // ------------------------------------------

  subtotal:
    Number(
      sourcePricing.subtotal ?? 0
    ),

  discount:
    Number(
      sourcePricing.discount ?? 0
    ),

  taxable_amount:
    Number(
      sourcePricing.taxable_amount ?? 0
    ),

  tax_rate:
    Number(
      sourcePricing.tax_rate ?? 0
    ),

  tax_amount:
    Number(
      sourcePricing.tax_amount ?? 0
    ),

  total:
    Number(
      sourcePricing.total ?? 0
    ),


  // ------------------------------------------
  // Phase-2 pricing fields
  // ------------------------------------------

  gross_subtotal:
    Number(
      sourcePricing.gross_subtotal ?? 0
    ),

  item_discount_total:
    Number(
      sourcePricing.item_discount_total ?? 0
    ),

  overall_discount:
    sourcePricing.overall_discount || {
      type: "fixed",
      value: 0,
      amount: 0
    },

  discounted_subtotal:
    Number(
      sourcePricing.discounted_subtotal ??
      sourcePricing.subtotal ??
      0
    ),

  additional_charges:
    Array.isArray(
      sourcePricing.additional_charges
    )
      ? sourcePricing.additional_charges.map(
          (charge) => ({
            name:
              charge.name || "Additional Charge",

            amount:
              Number(charge.amount || 0),

            taxable:
              charge.taxable ?? true
          })
        )
      : [],

  additional_charges_total:
    Number(
      sourcePricing.additional_charges_total ?? 0
    )
};


// ============================================================
// VALIDITY
// ============================================================

const validityDays =
  Number(
    data.validity_days || 0
  );

const createdDate =
  new Date(data.created_at);

if (
  Number.isNaN(
    createdDate.getTime()
  )
) {
  throw new Error(
    "Invalid created_at timestamp."
  );
}

let validUntil = null;

if (validityDays > 0) {

  createdDate.setDate(
    createdDate.getDate() +
    validityDays
  );

  validUntil =
    createdDate.toISOString();
}


// ============================================================
// BUSINESS PROFILE
// ============================================================
//
// Preserve a custom business object if it
// already exists.
//
// The Dynamic Business Profile node can
// replace this with the final default/custom
// business profile later.
// ============================================================

const business =
  input.business ||
  data.business ||
  null;


// ============================================================
// TEMPLATE
// ============================================================

const template =
  input.template ||
  data.template ||
  null;


// ============================================================
// CANONICAL QUOTE OBJECT
// ============================================================

const quote = {

  quote_id:
    data.quote_id,

  status:
    "DRAFT",

  created_at:
    data.created_at,

  customer,

  items,

  pricing,

  currency:
    data.currency || "INR",

  validity_days:
    validityDays,

  valid_until:
    validUntil,

  business
};


// ============================================================
// OPTIONAL TEMPLATE
// ============================================================

if (template) {
  quote.template =
    String(template).toLowerCase();
}


// ============================================================
// PRESERVE PROFILE METADATA
// ============================================================

if (
  input.business_profile &&
  typeof input.business_profile === "object"
) {
  quote.business_profile =
    input.business_profile;
}


// ============================================================
// RETURN
// ============================================================

return [
  {
    json: quote
  }
];

const input = $input.first().json;

// ============================================================
// DEFAULT BUSINESS PROFILE — SHINKA.AI
// ============================================================

const DEFAULT_BUSINESS = {
  brand_name: "SHINKA.AI",

  business_name: "Shinka-6c Automation",

  tagline: "Evolve • Automate • Scale",

  description:
    "AI-powered automation solutions for modern businesses.",

  positioning:
    "Next-Gen Autonomous Workforce",

  contact: {
    email: "chandouqiande@gmail.com",
    phone: "9704718538",
    address: "Bengaluru, India",
    website: "https://shinka-6c.netlify.app/"
  },

  branding: {
    logo_url:
      "https://drive.google.com/file/d/1NQ_TMvqbRcDeHOk3CUOwIRfsPRy-ys-j/view?usp=sharing",

    logo_file_id:
      "1NQ_TMvqbRcDeHOk3CUOwIRfsPRy-ys-j",

    primary_accent: "#7C3AED",
    secondary_accent: "#00BFFF"
  }
};


// ============================================================
// FIND OPTIONAL CUSTOM BUSINESS PROFILE
// ============================================================
//
// Phase 1:
// No business object → use Shinka defaults.
//
// Phase 2:
// Optional business object can be supplied either at:
//   $json.business
// or:
//   $json.data.business
//
// ============================================================

const customBusiness =
  input.business &&
  typeof input.business === "object"
    ? input.business
    : input.data?.business &&
      typeof input.data.business === "object"
      ? input.data.business
      : null;


// ============================================================
// HELPERS
// ============================================================

function cleanString(value) {
  if (
    value === undefined ||
    value === null
  ) {
    return "";
  }

  return String(value).trim();
}


function isHexColor(value) {
  return (
    typeof value === "string" &&
    /^#([0-9A-Fa-f]{3}|[0-9A-Fa-f]{6})$/.test(value.trim())
  );
}


// ============================================================
// BUILD CONTACT PROFILE
// ============================================================

const customContact =
  customBusiness?.contact &&
  typeof customBusiness.contact === "object"
    ? customBusiness.contact
    : {};

const contact = {
  email:
    cleanString(customContact.email) ||
    DEFAULT_BUSINESS.contact.email,

  phone:
    cleanString(customContact.phone) ||
    DEFAULT_BUSINESS.contact.phone,

  address:
    cleanString(customContact.address) ||
    DEFAULT_BUSINESS.contact.address,

  website:
    cleanString(customContact.website) ||
    DEFAULT_BUSINESS.contact.website
};


// ============================================================
// BUILD BRANDING PROFILE
// ============================================================

const customBranding =
  customBusiness?.branding &&
  typeof customBusiness.branding === "object"
    ? customBusiness.branding
    : {};

const primaryAccent =
  cleanString(customBranding.primary_accent);

const secondaryAccent =
  cleanString(customBranding.secondary_accent);

const branding = {
  logo_url:
    cleanString(customBranding.logo_url) ||
    DEFAULT_BUSINESS.branding.logo_url,

  logo_file_id:
    cleanString(customBranding.logo_file_id) ||
    DEFAULT_BUSINESS.branding.logo_file_id,

  primary_accent:
    isHexColor(primaryAccent)
      ? primaryAccent
      : DEFAULT_BUSINESS.branding.primary_accent,

  secondary_accent:
    isHexColor(secondaryAccent)
      ? secondaryAccent
      : DEFAULT_BUSINESS.branding.secondary_accent
};


// ============================================================
// BUILD FINAL BUSINESS PROFILE
// ============================================================

const business = {

  brand_name:
    cleanString(customBusiness?.brand_name) ||
    DEFAULT_BUSINESS.brand_name,

  business_name:
    cleanString(customBusiness?.business_name) ||
    DEFAULT_BUSINESS.business_name,

  tagline:
    cleanString(customBusiness?.tagline) ||
    DEFAULT_BUSINESS.tagline,

  description:
    cleanString(customBusiness?.description) ||
    DEFAULT_BUSINESS.description,

  positioning:
    cleanString(customBusiness?.positioning) ||
    DEFAULT_BUSINESS.positioning,

  contact,

  branding
};


// ============================================================
// PROFILE SOURCE
// ============================================================

const profileSource =
  customBusiness
    ? "custom"
    : "default_shinka";


// ============================================================
// RETURN
// ============================================================

return [
  {
    json: {
      ...input,

      business,

      business_profile: {
        source: profileSource,

        custom_profile_provided:
          Boolean(customBusiness)
      }
    }
  }
];

const quote = $input.first().json;

// ============================================================
// DATA
// ============================================================

const business = quote.business || {};
const customer = quote.customer || {};
const items = Array.isArray(quote.items) ? quote.items : [];
const pricing = quote.pricing || {};
const branding = business.branding || {};
const contact = business.contact || {};


// ============================================================
// CONFIGURATION
// ============================================================

const currencySymbols = {
  INR: "₹",
  USD: "$",
  EUR: "€",
  GBP: "£",
  JPY: "¥",
  CAD: "CA$",
  AUD: "A$",
  SGD: "S$"
};

const currencySymbol =
  currencySymbols[quote.currency] ||
  quote.currency ||
  "";


// ============================================================
// HELPERS
// ============================================================

function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}


function formatMoney(value) {
  const amount = Number(value || 0);

  return `${currencySymbol}${amount.toLocaleString("en-IN", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  })}`;
}


function formatDate(dateString) {
  if (!dateString) return "—";

  const date = new Date(dateString);

  if (Number.isNaN(date.getTime())) {
    return "—";
  }

  return date.toLocaleDateString("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric"
  });
}


function safe(value, fallback = "—") {
  const valueString = String(value ?? "").trim();

  return valueString
    ? escapeHtml(valueString)
    : fallback;
}


function optionalContactLine(value) {
  const valueString = String(value ?? "").trim();

  if (!valueString) return "";

  return `${escapeHtml(valueString)}<br>`;
}


// ============================================================
// BUSINESS VALUES
// ============================================================

const brandName =
  business.brand_name || "SHINKA.AI";

const businessName =
  business.business_name ||
  "Shinka-6c Automation";

const tagline =
  business.tagline ||
  "Evolve • Automate • Scale";

const positioning =
  business.positioning ||
  "Next-Gen Autonomous Workforce";

const primaryAccent =
  branding.primary_accent ||
