// ============================================================
// PHASE-2 TEMPLATE SELECTION
// ============================================================
//
// Priority:
// 1. Explicit template override
// 2. Work-type detection
// 3. Default → modern
//
// Supported:
//   modern
//   minimal
//
// ============================================================

const explicitTemplate =
  String(
    quote.template ||
    quote.data?.template ||
    ""
  )
    .trim()
    .toLowerCase();


// ------------------------------------------------------------
// Build searchable work description
// ------------------------------------------------------------

const workText = items
  .map((item) => {
    return [
      item.name,
      item.description
    ]
      .filter(Boolean)
      .join(" ");
  })
  .join(" ")
  .toLowerCase();


// ------------------------------------------------------------
// Modern work signals
// ------------------------------------------------------------

const modernKeywords = [
  "software",
  "website",
  "web development",
  "app development",
  "mobile app",
  "application",
  "ai",
  "artificial intelligence",
  "automation",
  "saas",
  "cloud",
