  "seo",
  "content",
  "video",
  "creative",
  "development",
  "data",
  "analytics"
];


// ------------------------------------------------------------
// Minimal work signals
// ------------------------------------------------------------

const minimalKeywords = [
  "consulting",
  "consultancy",
  "accounting",
  "bookkeeping",
  "audit",
  "legal",
  "law",
  "finance",
  "tax services",
