  "professional services",
  "training",
  "education",
  "administration"
];


// ------------------------------------------------------------
// Score work type
// ------------------------------------------------------------

function countKeywordMatches(text, keywords) {
  return keywords.reduce(
    (score, keyword) => {
      return score +
        (text.includes(keyword) ? 1 : 0);
    },
    0
  );
}

const modernScore =
  countKeywordMatches(
    workText,
    modernKeywords
  );

const minimalScore =
  countKeywordMatches(
    workText,
    minimalKeywords
  );


// ------------------------------------------------------------
// Determine template
// ------------------------------------------------------------

let selectedTemplate = "modern";

let templateSelectionReason =
  "Default modern template.";

if (
  explicitTemplate === "modern" ||
  explicitTemplate === "minimal"
) {

  selectedTemplate =
    explicitTemplate;

  templateSelectionReason =
    "Explicit template override.";

} else if (
  minimalScore > modernScore &&
  minimalScore > 0
) {

  selectedTemplate = "minimal";

  templateSelectionReason =
    "Traditional/professional service detected.";

} else if (
  modernScore > 0
) {

  selectedTemplate = "modern";

  templateSelectionReason =
    "Digital/technical/creative service detected.";

}


