// ITEM ROWS
// ============================================================

const itemRows = items.length
  ? items
      .map((item) => {

        const quantity =
          Number(item.quantity || 0);

        const unitPrice =
          Number(item.unit_price || 0);

        const lineTotal =
          Number(
            item.line_total ??
            quantity * unitPrice
          );

        const itemDiscount =
          Number(
            item.item_discount?.amount ||
            0
          );

        return `
          <tr>

            <td class="service-cell">

              <div class="service-name">
                ${safe(
                  item.name,
                  "Unnamed Service"
                )}
              </div>

              ${
                item.description
                  ? `
