                      ${escapeHtml(
                        item.description
                      )}
                    </div>
                  `
                  : ""
              }

            </td>

            <td class="qty-cell">
              ${quantity}
            </td>

            <td class="price-cell">
              ${formatMoney(unitPrice)}
            </td>

            <td class="amount-cell">
              ${formatMoney(lineTotal)}
            </td>

          </tr>
        `;
      })
      .join("")
  : `
