  justify-content:
    space-between;

  align-items:
    flex-start;

  padding-bottom: 18px;

  margin-bottom: 22px;

  border-bottom:
    2px solid ${primaryAccent};
}


.brand {
  display: flex;

  align-items: center;

  gap: 12px;
}


.logo {
  width: 50px;
  height: 50px;

  display: block;

  object-fit: contain;

  border-radius: 8px;

  background: transparent;
}


img.logo {
  width: 50px;
  height: 50px;

  object-fit: contain;

  border-radius: 8px;
}


.brand-name {
  font-size: 18px;

  font-weight: 800;

  color: #111827;
}


.brand-tagline {
  margin-top: 4px;

  font-size: 7px;

  letter-spacing: 1.3px;

  text-transform: uppercase;

  color: #667085;
}


.brand-positioning {
  margin-top: 3px;

  font-size: 7.5px;

  color: #98a2b3;
}


.quote-heading {
  text-align: right;
}


.quote-title {
  margin: 0;

  font-size: 23px;

  font-weight: 800;

  color: #111827;
}


.quote-number {
  margin-top: 6px;

  font-size: 8.5px;

  font-weight: 700;

  color: ${primaryAccent};
}


.quote-meta {
  margin-top: 6px;

  font-size: 7.5px;

  line-height: 1.5;

  color: #667085;
}


/* ------------------------------------------------------------
   INTRO
------------------------------------------------------------ */

.introduction {
  margin-bottom: 22px;
}


.introduction-title {
  margin-bottom: 5px;

  font-size: 9px;

  font-weight: 700;

  color: #344054;
}


.introduction-text {
  max-width: 78%;

  font-size: 8px;

  line-height: 1.6;

  color: #667085;
}


/* ------------------------------------------------------------
   INFO
------------------------------------------------------------ */

.info-grid {
  display: grid;

  grid-template-columns:
    1fr 1fr;

  gap: 30px;

  margin-bottom: 25px;
}


.info-card {
  padding: 0;

  border: none;

  background: transparent;
}


.info-label {
  margin-bottom: 7px;

  padding-bottom: 5px;

  border-bottom:
    1px solid #e5e7eb;

  font-size: 7px;

  font-weight: 800;

  letter-spacing: 1.2px;

  text-transform: uppercase;

  color: ${primaryAccent};
}


.info-name {
  margin-top: 9px;

  margin-bottom: 6px;

  font-size: 11px;

  font-weight: 750;

  color: #172033;
}


.info-details {
  font-size: 8px;

  line-height: 1.7;

  color: #667085;
}


.info-details a {
  color: inherit;

  text-decoration: none;
}


/* ------------------------------------------------------------
   SERVICES
------------------------------------------------------------ */

.services-section {
  margin-bottom: 22px;
}


.services-heading {
  margin-bottom: 9px;
}


.services-title {
  font-size: 10px;

  font-weight: 800;

  color: #172033;
}


.services-subtitle {
  margin-top: 3px;

  font-size: 7px;

  color: #98a2b3;
}


table {
  width: 100%;

  border-collapse:
    collapse;

  table-layout: fixed;
}


thead {
  border-top:
    1px solid #d0d5dd;

  border-bottom:
    1px solid #d0d5dd;
}


thead th {
  padding: 9px 7px;

  font-size: 7px;

  font-weight: 800;

  letter-spacing: 0.8px;

  text-transform: uppercase;

  color: #667085;

  text-align: left;
}


thead th:nth-child(1) {
  width: 50%;
}

thead th:nth-child(2) {
  width: 11%;

  text-align: center;
}

thead th:nth-child(3) {
  width: 19%;

  text-align: right;
}

thead th:nth-child(4) {
  width: 20%;

  text-align: right;
}


tbody tr {
  border-bottom:
    1px solid #eaecf0;

  page-break-inside:
    avoid;
}


tbody td {
  padding: 13px 7px;

  vertical-align: top;

  font-size: 8px;

  color: #344054;
}


.service-name {
