  font-weight: 800;

  letter-spacing: 1px;

  text-transform: uppercase;

  color: #667085;
}


.total-note {
  margin-top: 2px;

  font-size: 6.5px;

  color: #98a2b3;
}


.total-value {
  font-size: 17px;

  font-weight: 800;

  color: ${primaryAccent};
}


/* ------------------------------------------------------------
   TERMS
------------------------------------------------------------ */

.terms-section {
  padding-top: 16px;

  border-top:
    1px solid #eaecf0;
}


.terms-heading {
  margin-bottom: 9px;

  font-size: 7.5px;

  font-weight: 800;

  letter-spacing: 1.1px;

  text-transform: uppercase;

  color: #344054;
}


.terms-grid {
