`;


// ============================================================
// SELECT TEMPLATE
// ============================================================

const finalHtml =
  selectedTemplate === "minimal"
    ? minimalTemplate
    : modernTemplate;


// ============================================================
// RETURN
// ============================================================

return [
  {
    json: {
      ...quote,

      template: selectedTemplate,

      template_selection: {
        mode:
          explicitTemplate
            ? "manual"
            : "automatic",

        selected:
          selectedTemplate,

        modern_score:
          modernScore,

        minimal_score:
          minimalScore,

        reason:
          templateSelectionReason
      },

      document: {
        type: "quotation",

        format: "html",

        template:
          selectedTemplate,

        html:
          `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta
  name="viewport"
  content="width=device-width, initial-scale=1.0"
/>
<title>
  ${escapeHtml(
    brandName
  )}
  — Quotation
  ${escapeHtml(
    quote.quote_id
  )}
</title>
</head>
<body>
${finalHtml}
</body>
</html>`
      }
    }
  }
];

const input = $input.first();

// ============================================================
// 1. VALIDATE QUOTATION HTML
// ============================================================

const html = input.json.document?.html;

if (!html) {
  throw new Error(
    "Quotation HTML was not found in document.html."
  );
}


// ============================================================
// 2. VALIDATE LOGO BINARY
// ============================================================

if (!input.binary?.data) {
  throw new Error(
    "Logo binary data was not found in binary.data."
  );
}


// ============================================================
// 3. GET LOGO BUFFER
// ============================================================

const logoBuffer = await this.helpers.getBinaryDataBuffer(
  0,
  "data"
);

if (!logoBuffer || logoBuffer.length === 0) {
  throw new Error(
    "Logo binary buffer is empty."
  );
}


// ============================================================
// 4. GET MIME TYPE
// ============================================================

const mimeType =
  input.binary.data.mimeType || "image/png";


// ============================================================
// 5. VALIDATE MIME TYPE
// ============================================================

if (!mimeType.startsWith("image/")) {
  throw new Error(
    `Invalid logo MIME type: ${mimeType}`
  );
}


// ============================================================
// 6. CONVERT LOGO TO BASE64
// ============================================================

const base64 = logoBuffer.toString("base64");

if (!base64 || base64.length < 20) {
  throw new Error(
    "Logo could not be converted to a valid Base64 string."
  );
}


// ============================================================
// 7. CREATE DATA URI
// ============================================================

const logoDataUri =
  `data:${mimeType};base64,${base64}`;


// ============================================================
// 8. FIND EXACT SHINKA LOGO PLACEHOLDER
// ============================================================

const placeholderRegex =
  /<div\b(?=[^>]*\bid=["']shinka-logo-placeholder["'])[^>]*>[\s\S]*?<\/div>/i;


if (!placeholderRegex.test(html)) {
  throw new Error(
    "Shinka logo placeholder was not found in document.html. " +
    'Expected id="shinka-logo-placeholder".'
  );
}


// ============================================================
// 9. CREATE REAL LOGO ELEMENT
// ============================================================

const brandName =
  input.json.business?.brand_name ||
  "SHINKA.AI";

const logoHtml = `
<img
  id="shinka-logo-placeholder"
  class="logo"
  src="${logoDataUri}"
  alt="${brandName}"
/>
`.trim();


// ============================================================
// 10. REPLACE PLACEHOLDER
// ============================================================

const updatedHtml = html.replace(
  placeholderRegex,
  logoHtml
);


// ============================================================
// 11. VERIFY PLACEHOLDER WAS REMOVED
// ============================================================

if (
  placeholderRegex.test(updatedHtml)
) {
  throw new Error(
    "Logo placeholder still exists after replacement."
  );
}


// ============================================================
// 12. VERIFY BASE64 IMAGE EXISTS
// ============================================================

if (
  !updatedHtml.includes("data:image/")
) {
  throw new Error(
    "Base64 image data was not inserted into the HTML."
  );
}


// ============================================================
// 13. VERIFY IMAGE ELEMENT EXISTS
// ============================================================

if (
  !updatedHtml.includes(
    'id="shinka-logo-placeholder"'
  )
) {
  throw new Error(
    "Final logo <img> element was not found."
  );
}


// ============================================================
// 14. RETURN UPDATED QUOTE
// ============================================================

return [
  {
    json: {
      ...input.json,

      document: {
        ...input.json.document,

        html: updatedHtml,

        logo_embedded: true,

        logo_mime_type: mimeType,

        logo_base64_length: base64.length
      }
    }
  }
];

