    "ACCEPTED",
    "REJECTED",
    "EXPIRED"
  ];

  const isTerminalStatus =
    terminalStatuses.includes(status);


  // ============================================================
  // EXPIRY CHECK
  // ============================================================

  const validUntil = quote.valid_until
    ? new Date(quote.valid_until)
    : null;

  const isExpired =
    !isTerminalStatus &&
    validUntil instanceof Date &&
    !isNaN(validUntil) &&
