  // FOLLOW-UP VALUES
  // ============================================================

  const followUpCount =
    Number(quote.follow_up_count || 0);

  const sentAt = quote.sent_at
    ? new Date(quote.sent_at)
    : null;

  let nextFollowUpAt = quote.next_follow_up_at
    ? new Date(quote.next_follow_up_at)
    : null;


