// ============================================================

if (!data.quote_id) {
  throw new Error("Quote ID is missing.");
}

if (!data.created_at) {
  throw new Error("Created timestamp is missing.");
}

if (
  !data.customer ||
  typeof data.customer !== "object"
) {
  throw new Error("Customer data is missing.");
}

if (
  !Array.isArray(data.items)
) {
  throw new Error("Items array is missing.");
}

if (
  !data.pricing ||
  typeof data.pricing !== "object"
) {
  throw new Error(
    "Pricing data is missing. " +
    "Quote Object must receive the output of the Advanced Pricing Engine."
  );
}


// ============================================================
