const items = data.items.map((item) => {

  const quantity =
    Number(item.quantity || 0);

  const unitPrice =
    Number(item.unit_price || 0);

  const lineTotal =
    Number(
      item.line_total ??
      item.gross_line_total ??
      quantity * unitPrice
    );

  return {
    name:
      item.name || "",

