const quote = $('Save Quote Record').first().json;

if (!quote.quote_id) {
  throw new Error("Quote ID not found.");
}

const sentAt = new Date().toISOString();

return [
  {
    json: {
      quote_id: quote.quote_id,
      status: "SENT",
      sent_at: sentAt
    }
  }
];

const quote = $input.first().json;

const now = new Date();
const validUntil = new Date(quote.valid_until);

if (Number.isNaN(validUntil.getTime())) {
  throw new Error("Invalid or missing valid_until date.");
}

const isExpired = now > validUntil;

return [
  {
    json: {
      ...quote,

      is_expired: isExpired,

      current_time: now.toISOString(),

      view_action: isExpired
        ? "EXPIRED"
        : "VIEWED"
    }
  }
];

const input = $input.first().json;

const quoteId = input.query?.quote_id;

if (!quoteId) {
  throw new Error("quote_id is required.");
}

return [
