      action
    }
  }
];

const quote = $input.first().json;

if (!quote.quote_id) {
  throw new Error("Quote ID was not found.");
}

if (!quote.valid_until) {
  throw new Error(
    `Valid until date was not found for quote ${quote.quote_id}.`
  );
}

const now = new Date();

const validUntil = new Date(quote.valid_until);

if (Number.isNaN(validUntil.getTime())) {
  throw new Error(
    `Invalid valid_until date for quote ${quote.quote_id}.`
  );
}

// Check whether the quotation has expired
const isExpired = now.getTime() > validUntil.getTime();

return [
  {
    json: {
      ...quote,

      is_expired: isExpired,

      current_time: now.toISOString(),

      reject_action: isExpired
        ? "REJECT_ATTEMPT_AFTER_EXPIRY"
        : "REJECTED"
    }
  }
];

const quote = $input.first().json;

const now = new Date().toISOString();

return [
  {
    json: {
      ...quote,

      // Update quote status
      status: "REJECTED",

      // Lifecycle tracking
      rejected_at: now,

      // Customer action tracking
      customer_action: "REJECTED",

      customer_action_at: now
    }
  }
];

const quote = $input.first().json;

const now = new Date().toISOString();

return [
  {
    json: {
      ...quote,

      // Quote can no longer be acted upon
      status: "EXPIRED",

      // Lifecycle tracking
      expired_at: now,

      // Record what happened
      customer_action: "REJECT_ATTEMPT_AFTER_EXPIRY",

      customer_action_at: now
    }
  }
];

const quoteId = $json.query?.quote_id;

if (!quoteId) {
  throw new Error("Quote ID is missing.");
}

return [
  {
    json: {
      quote_id: quoteId
    }
  }
];

const now = new Date();

const FOLLOW_UP_AFTER_DAYS = 3;
const MAX_FOLLOW_UPS = 5;

return $input.all().map((item) => {
  const quote = item.json;

  const status = String(quote.status || "").toUpperCase();

  // ============================================================
  // TERMINAL STATUS
  // ============================================================

  const terminalStatuses = [
    "ACCEPTED",
    "REJECTED",
    "EXPIRED"
  ];

  const isTerminalStatus =
    terminalStatuses.includes(status);


  // ============================================================
  // EXPIRY CHECK
  // ============================================================

  const validUntil = quote.valid_until
    ? new Date(quote.valid_until)
    : null;

  const isExpired =
    !isTerminalStatus &&
    validUntil instanceof Date &&
    !isNaN(validUntil) &&
    now > validUntil;


  // ============================================================
  // FOLLOW-UP VALUES
  // ============================================================

  const followUpCount =
    Number(quote.follow_up_count || 0);

  const sentAt = quote.sent_at
    ? new Date(quote.sent_at)
    : null;

  let nextFollowUpAt = quote.next_follow_up_at
    ? new Date(quote.next_follow_up_at)
    : null;


  // If next_follow_up_at is empty,
  // calculate it as sent_at + 3 days
  if (
    !nextFollowUpAt &&
    sentAt instanceof Date &&
    !isNaN(sentAt)
  ) {
    nextFollowUpAt = new Date(sentAt);

    nextFollowUpAt.setDate(
      nextFollowUpAt.getDate() + FOLLOW_UP_AFTER_DAYS
    );
  }


  // ============================================================
  // FOLLOW-UP ELIGIBILITY
  // ============================================================

  const isActiveQuote =
    status === "SENT" ||
    status === "VIEWED";

  const hasFollowUpsRemaining =
    followUpCount < MAX_FOLLOW_UPS;

  const isFollowUpDue =
    isActiveQuote &&
    !isTerminalStatus &&
    !isExpired &&
    hasFollowUpsRemaining &&
    nextFollowUpAt instanceof Date &&
    !isNaN(nextFollowUpAt) &&
    now >= nextFollowUpAt;


  // ============================================================
  // RETURN ENRICHED QUOTE
  // ============================================================

  return {
    json: {
      ...quote,

      current_time: now.toISOString(),

      is_terminal_status: isTerminalStatus,

      is_expired: isExpired,

      follow_up_count: followUpCount,

      next_follow_up_at:
        nextFollowUpAt
          ? nextFollowUpAt.toISOString()
          : null,

      is_follow_up_due: isFollowUpDue
    }
  };
});

const quote = $json;

const now = new Date().toISOString();

const followUpCount = Number(quote.follow_up_count || 0);

// Determine which follow-up this is
const nextFollowUpCount = followUpCount + 1;

return {
  json: {
    ...quote,

    // Follow-up metadata
    follow_up_number: nextFollowUpCount,

    follow_up_subject:
      `Follow-up: Your quotation ${quote.quote_id}`,

    follow_up_sent_at: now,

    // Useful formatted values for email
    formatted_total: new Intl.NumberFormat('en-IN', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(Number(quote.total || 0)),

    formatted_valid_until: new Date(
      quote.valid_until
    ).toLocaleDateString('en-IN', {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
    }),
  },
};

const now = new Date();

// Increment follow-up count
const followUpCount = Number($json.follow_up_count || 0) + 1;

// Calculate next follow-up date: 3 days from now
const nextFollowUp = new Date(now);
nextFollowUp.setDate(nextFollowUp.getDate() + 3);

return {
  json: {
    ...$json,

    follow_up_count: followUpCount,

    last_follow_up_at: now.toISOString(),

    next_follow_up_at: nextFollowUp.toISOString(),

    is_follow_up_due: false
  }
};
